//! conda-forge builds of PyPI packages that are painful to install from PyPI.
//!
//! The table (`data/conda_forge_packages.json`, generated by
//! `scripts/gen_conda_forge.py`) lists PyPI packages whose source build needs
//! system libraries (or nvcc) that pip and uv cannot install, the conda-forge
//! package that ships them, and where conda-forge builds it. It also maps the
//! names a failed build prints (a missing header, a `*-config` tool, a
//! pkg-config module, a shared library) to the conda-forge package providing
//! them. [`crate::core::pixi_advice`] turns both into the "pixi can help
//! here" advisory.

use serde::Deserialize;

use crate::core::platform::{Arch, Os, Platform};
use crate::core::project::normalize_name;
use crate::pypi::PyVersion;

#[derive(Debug, Default, Deserialize)]
pub struct CondaForgeTable {
    #[serde(default)]
    packages: Vec<CondaPackage>,
    #[serde(default)]
    libraries: Vec<Library>,
}

/// One PyPI package and its conda-forge build.
#[derive(Debug, Clone, Deserialize)]
pub struct CondaPackage {
    /// PyPI distribution name.
    pub pypi: String,
    /// conda-forge package name (`pytables` for `tables`).
    pub conda: String,
    /// Newest conda-forge version when the table was generated.
    pub version: String,
    builds: Vec<Build>,
    /// conda-forge names of the native libraries it needs.
    #[serde(default)]
    pub system_libs: Vec<String>,
    /// Why it is painful from PyPI, as a clause: "it builds against ...".
    #[serde(default)]
    pub why: String,
    /// Its source build compiles CUDA code, so it needs nvcc.
    #[serde(default)]
    pub needs_nvcc: bool,
}

#[derive(Debug, Clone, Deserialize)]
struct Build {
    /// A conda subdir (`linux-64`, `win-64`, ...) or `noarch`.
    platform: String,
    /// CPython minors built for. Empty: not tied to a Python ABI.
    #[serde(default)]
    python: Vec<String>,
}

/// What a failed build can name, and the conda-forge package providing it.
#[derive(Debug, Clone, Deserialize)]
pub struct Library {
    /// `header`, `tool`, `pkg-config` or `library`.
    pub kind: String,
    pub name: String,
    pub conda: String,
}

/// Where conda-forge has a package for this machine.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Availability {
    /// Built for this platform, and for the Python asked about (if any).
    Yes,
    /// Built for this platform, but not for the Python asked about; these
    /// are the Pythons it is built for.
    OtherPythons(Vec<PyVersion>),
    /// Not built for this platform.
    No,
}

/// The conda subdir for a platform. Windows on Arm has too few conda-forge
/// builds to promise anything.
pub fn conda_subdir(platform: Platform) -> Option<&'static str> {
    Some(match (platform.os, platform.arch) {
        (Os::Linux, Arch::X86_64) => "linux-64",
        (Os::Linux, Arch::Aarch64) => "linux-aarch64",
        (Os::Macos, Arch::X86_64) => "osx-64",
        (Os::Macos, Arch::Aarch64) => "osx-arm64",
        (Os::Windows, Arch::X86_64) => "win-64",
        (Os::Windows, Arch::Aarch64) => return None,
    })
}

impl CondaForgeTable {
    pub fn load(json: &str) -> Option<CondaForgeTable> {
        serde_json::from_str(json).ok()
    }

    pub fn empty() -> CondaForgeTable {
        CondaForgeTable::default()
    }

    pub fn len(&self) -> usize {
        self.packages.len()
    }

    pub fn is_empty(&self) -> bool {
        self.packages.is_empty()
    }

    /// The row for a PyPI name, matched normalized.
    pub fn get(&self, pypi: &str) -> Option<&CondaPackage> {
        let want = normalize_name(pypi);
        self.packages
            .iter()
            .find(|p| normalize_name(&p.pypi) == want)
    }

    /// The conda-forge package providing `name` of `kind`. Headers also
    /// match on their file name (`gdal/gdal.h` finds `gdal.h`); shared
    /// libraries match on a prefix (`libGL.so.1.7.0` finds `libGL.so.1`,
    /// `libmagic.so.1` finds `libmagic`).
    pub fn library(&self, kind: &str, name: &str) -> Option<&Library> {
        let rows = || self.libraries.iter().filter(move |l| l.kind == kind);
        if let Some(l) = rows().find(|l| l.name == name) {
            return Some(l);
        }
        match kind {
            "header" => {
                let file = name.rsplit('/').next().unwrap_or(name);
                rows().find(|l| l.name == file)
            }
            "library" => rows()
                .filter(|l| name.starts_with(l.name.as_str()))
                .max_by_key(|l| l.name.len()),
            "tool" => rows().find(|l| l.name.eq_ignore_ascii_case(name)),
            _ => None,
        }
    }
}

impl CondaPackage {
    /// Is it built for `platform` (and `python`, when given)?
    pub fn availability(&self, platform: Platform, python: Option<PyVersion>) -> Availability {
        if self.builds.iter().any(|b| b.platform == "noarch") {
            return Availability::Yes;
        }
        let Some(subdir) = conda_subdir(platform) else {
            return Availability::No;
        };
        let Some(build) = self.builds.iter().find(|b| b.platform == subdir) else {
            return Availability::No;
        };
        let pythons: Vec<PyVersion> = build
            .python
            .iter()
            .filter_map(|s| PyVersion::parse(s))
            .collect();
        match python {
            Some(py) if !pythons.is_empty() && !pythons.contains(&py) => {
                Availability::OtherPythons(pythons)
            }
            _ => Availability::Yes,
        }
    }

    /// The Pythons conda-forge builds it for on `platform` (empty: any).
    pub fn pythons(&self, platform: Platform) -> Vec<PyVersion> {
        let Some(subdir) = conda_subdir(platform) else {
            return Vec::new();
        };
        self.builds
            .iter()
            .find(|b| b.platform == subdir)
            .map(|b| {
                b.python
                    .iter()
                    .filter_map(|s| PyVersion::parse(s))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// The conda platforms it is built for (`noarch` for pure packages).
    pub fn platforms(&self) -> Vec<&str> {
        self.builds.iter().map(|b| b.platform.as_str()).collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn linux() -> Platform {
        Platform {
            os: Os::Linux,
            arch: Arch::X86_64,
        }
    }

    fn table() -> CondaForgeTable {
        CondaForgeTable::load(crate::matrix::CONDA_FORGE_JSON).expect("bundled table parses")
    }

    #[test]
    fn bundled_table_is_substantial_and_knows_the_classics() {
        let t = table();
        assert!(t.len() > 100, "{} rows", t.len());
        for name in ["gdal", "GDAL", "psycopg2", "pygraphviz", "dlib", "tables"] {
            assert!(t.get(name).is_some(), "{name}");
        }
        assert_eq!(t.get("tables").unwrap().conda, "pytables");
        assert!(t.get("flash_attn").unwrap().needs_nvcc);
        assert!(t.get("requests").is_none());
    }

    #[test]
    fn availability_follows_platform_and_python() {
        let t = table();
        let gdal = t.get("gdal").unwrap();
        assert_eq!(gdal.availability(linux(), None), Availability::Yes);
        let newest = *gdal.pythons(linux()).last().unwrap();
        assert_eq!(gdal.availability(linux(), Some(newest)), Availability::Yes);
        assert!(matches!(
            gdal.availability(linux(), Some(PyVersion::py3(7))),
            Availability::OtherPythons(_)
        ));
        let win_arm = Platform {
            os: Os::Windows,
            arch: Arch::Aarch64,
        };
        assert_eq!(gdal.availability(win_arm, None), Availability::No);
        // flash-attn is built for Linux only.
        let mac = Platform {
            os: Os::Macos,
            arch: Arch::Aarch64,
        };
        let fa = t.get("flash-attn").unwrap();
        assert_eq!(fa.availability(mac, None), Availability::No);
    }

    #[test]
    fn libraries_match_by_exact_name_file_name_and_prefix() {
        let t = table();
        assert_eq!(t.library("header", "gdal.h").unwrap().conda, "libgdal");
        assert_eq!(
            t.library("header", "some/dir/geos_c.h").unwrap().conda,
            "geos"
        );
        assert_eq!(
            t.library("header", "graphviz/cgraph.h").unwrap().conda,
            "graphviz"
        );
        assert_eq!(t.library("tool", "pg_config").unwrap().conda, "libpq");
        assert_eq!(t.library("library", "libGL.so.1").unwrap().conda, "libgl");
        assert_eq!(
            t.library("library", "libmagic.so.1").unwrap().conda,
            "libmagic"
        );
        assert_eq!(t.library("pkg-config", "cairo").unwrap().conda, "cairo");
        assert!(t.library("header", "stdio.h").is_none());
    }
}
